param([Parameter(Mandatory=$true)][string]$RunId,[string]$RunDate=(Get-Date -Format yyyyMMdd),[ValidateSet(400,1000)][int]$PoolMaxConnections=1000,[string]$ExperimentId='1-33',[string]$Condition='POOL1000',[switch]$Core)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$artifact=Join-Path $root "backend\experiments\results\experiment-$ExperimentId\$Condition\$RunId";$legacy=Join-Path $root "experiment\results\$RunId";$project="doeng-exp$ExperimentId-$PoolMaxConnections";$loadUsers=if($Core){200}else{20};$loadDuration=if($Core){105000}else{5000};$drainSeconds=if($Core){30}else{10}
$files=@('backend\docker-compose.experiment.yaml','backend\docker-compose.app-instance-t3-medium.yaml','backend\docker-compose.mock-headroom-4cpu.yaml','backend\docker-compose.http-pool-400.yaml','backend\docker-compose.mock-memory-headroom.yaml','backend\docker-compose.experiment-1-12-connection-attribution.yaml','backend\docker-compose.experiment-1-19-fresh-first-lifecycle.yaml','backend\docker-compose.experiment-1-31-diagnostics.yaml',"backend\docker-compose.experiment-$ExperimentId-pool-$PoolMaxConnections.yaml");$compose=@();foreach($f in $files){$compose+=@('-f',(Join-Path $root $f))};$collector=$null;$smoke=$null;$failure=$null;$old=@();$collectorMaxDuration=if($Core){300}else{60}
function W([string]$p,[object]$v){New-Item -ItemType Directory -Force (Split-Path -Parent $p)|Out-Null;[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 40),(New-Object Text.UTF8Encoding($false)))}
function J([string]$p){Get-Content -Raw $p|ConvertFrom-Json}
try{
  if(Test-Path $artifact){throw "ARTIFACT_COLLISION: $artifact"};if(Test-Path $legacy){throw "LEGACY_COLLISION: $legacy"};New-Item -ItemType Directory -Force $artifact|Out-Null;W (Join-Path $artifact 'exp131-run-config.json') ([ordered]@{runId=$RunId;runDate=$RunDate;phase='preflight';admissionMode='OFF';admissionEnabled=$false;poolMode='SHARED';sharedPoolMaxConnections=$PoolMaxConnections;pendingAcquireMaxCount=800;identityProfiles=@('TOKEN_ONLY','AI_ONLY','STORAGE_ONLY','COMBINED');runnerStartedAt=[DateTimeOffset]::UtcNow.ToString('o')})
  $env:DOENG_EXP119_APP_IMAGE='doeng-exp133-admission-off:a530aa6';$env:DOENG_EXP119_MOCK_IMAGE='doeng-exp119-mock-frozen-20260803:latest'
  docker compose -p $project @compose config|Set-Content (Join-Path $artifact 'rendered-compose.yaml') -Encoding utf8;if($LASTEXITCODE){throw 'COMPOSE_CONFIG_FAILED'};$renderedComposeText=Get-Content (Join-Path $artifact 'rendered-compose.yaml') -Raw;$renderedMatches=[regex]::Matches($renderedComposeText,'DOENG_SHARED_POOL_MAX_CONNECTIONS:\s+"?(\d+)');if($renderedMatches.Count -eq 0){throw 'RENDERED_POOL_PROVENANCE_MISSING'};$renderedPoolMax=[int]$renderedMatches[0].Groups[1].Value
  docker compose -p $project @compose up -d --force-recreate --no-build mariadb experiment-mock flux-corrected | Out-Null;if($LASTEXITCODE){throw 'FRESH_RECREATE_FAILED'};$cid=(docker compose -p $project @compose ps -q flux-corrected).Trim();if(-not $cid){throw 'APPLICATION_CONTAINER_ID_MISSING'}
  $ready=$false;for($i=0;$i -lt 60 -and -not $ready;$i++){try{$h=Invoke-RestMethod 'http://127.0.0.1:9001/actuator/health';$a=Invoke-RestMethod 'http://127.0.0.1:9001/actuator/doengadmission';$id=Invoke-RestMethod 'http://127.0.0.1:9001/actuator/doengidentity';$ready=($h.status -eq 'UP' -and $null -ne $a.mode -and $null -ne $id.clients)}catch{};if(-not $ready){Start-Sleep -Seconds 1}};if(-not $ready){throw 'DIAGNOSTIC_ENDPOINT_NOT_READY'}
  $inspect=@(docker inspect $cid|ConvertFrom-Json)[0];$allow=@('DOENG_ADMISSION_MODE','DOENG_AI_ADMISSION_ENABLED','DOENG_AI_ADMISSION_MAX_CONCURRENT','DOENG_ADMISSION_SCOPE','DOENG_EXTERNAL_POOL_MODE','DOENG_SHARED_POOL_MAX_CONNECTIONS','DOENG_SHARED_POOL_PENDING_MAX_COUNT');$envRows=@();foreach($e in $inspect.Config.Env){$k=($e -split '=',2)[0];if($k -in $allow){$envRows+=$e}};W (Join-Path $artifact 'runtime-container-environment.json') ([ordered]@{containerId=$cid;capturedAt=[DateTimeOffset]::UtcNow.ToString('o');variables=$envRows});$runtimePoolRow=$envRows|Where-Object{$_ -like 'DOENG_SHARED_POOL_MAX_CONNECTIONS=*'}|Select-Object -First 1;if(-not $runtimePoolRow){throw 'RUNTIME_POOL_PROVENANCE_MISSING'};$runtimePoolMax=[int](($runtimePoolRow -split '=',2)[1]);$provenance=[ordered]@{runId=$RunId;condition=$Condition;planned=[ordered]@{sharedPoolMaxConnections=$PoolMaxConnections};rendered=[ordered]@{sharedPoolMaxConnections=$renderedPoolMax};runtime=[ordered]@{sharedPoolMaxConnections=$runtimePoolMax};provenanceConsistent=($PoolMaxConnections -eq $renderedPoolMax -and $renderedPoolMax -eq $runtimePoolMax);capturedAt=[DateTimeOffset]::UtcNow.ToString('o')};W (Join-Path $artifact 'exp133-run-config.json') $provenance;if(-not $provenance.provenanceConsistent){throw 'POOL_PROVENANCE_MISMATCH'}
  $admissionBefore=Invoke-RestMethod http://127.0.0.1:9001/actuator/doengadmission;W (Join-Path $artifact 'admission-metrics-before.json') $admissionBefore;$identityUrl='http://127.0.0.1:9001/actuator/doengidentity';$registryBefore=Invoke-RestMethod $identityUrl;W (Join-Path $artifact 'meter-registry-before.json') $registryBefore
  $profiles=@('TOKEN_ONLY','AI_ONLY','STORAGE_ONLY','COMBINED');$probes=@();foreach($profile in $profiles){$before=Invoke-RestMethod $identityUrl;$probes+=[ordered]@{profile=$profile;capturedAt=[DateTimeOffset]::UtcNow.ToString('o');identity=$before;activeDelta='NOT_AVAILABLE';totalDelta='NOT_AVAILABLE';idleDelta='NOT_AVAILABLE';pendingDelta='NOT_AVAILABLE'}};W (Join-Path $artifact 'pool-provider-identity.json') ([ordered]@{profiles=$probes;source='diagnostic endpoint';registryIdentity=$registryBefore.meterRegistry.identity})
  $staging=Join-Path $artifact 'pool';$stop=Join-Path $staging 'STOP-COLLECTOR';$collector=Start-Process powershell.exe -WindowStyle Hidden -PassThru -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $PSScriptRoot 'collect-exp131-pool.ps1'),'-ManagementUrl','http://127.0.0.1:9001','-OutputPath',(Join-Path $staging 'pool-metrics.jsonl'),'-FailurePath',(Join-Path $staging 'collector-failures.jsonl'),'-SummaryPath',(Join-Path $staging 'pool-metrics.jsonl.summary.json'),'-StopSignalPath',$stop,'-MaxDurationSeconds',"$collectorMaxDuration")
 $smokeOut=Join-Path $artifact 'lifecycle-smoke.stdout.log';$smokeErr=Join-Path $artifact 'lifecycle-smoke.stderr.log';$smokeArgs=@('-NoProfile','-ExecutionPolicy','Bypass','-File',(Join-Path $PSScriptRoot 'run-isolated-vu-success-smoke.ps1'),'-RunId',$RunId,'-Implementation',"Exp133-$Condition",'-TargetUrl','http://127.0.0.1:8001/game/face','-ServerService','flux-corrected','-ComposeProject',$project,'-ComposeFiles',($files -join ','),'-ActiveMissions',"$loadUsers",'-AiDelayMs','2000','-StorageDelayMs','100','-IntervalMs','1000','-DurationMs',"$loadDuration",'-RequestTimeoutMs','10000','-TargetP95Ms','10000','-EnableObservability','1','-EnableJfr','0','-EnableContainerMonitor','1','-SkipApplicationSnapshot','1','-SkipMockMetrics','1','-OutcomeMode','natural-capacity','-AccountingMode','corrected','-DrainObservationSeconds',"$drainSeconds");$smoke=Start-Process powershell.exe -WindowStyle Hidden -PassThru -RedirectStandardOutput $smokeOut -RedirectStandardError $smokeErr -ArgumentList $smokeArgs;Start-Sleep -Seconds 2;$admissionDuring=Invoke-RestMethod http://127.0.0.1:9001/actuator/doengadmission;W (Join-Path $artifact 'admission-metrics-during.json') $admissionDuring;$smoke.WaitForExit();$smokeExit=$smoke.ExitCode
  New-Item -ItemType File -Force $stop|Out-Null;if(-not $collector.WaitForExit(15000)){throw 'COLLECTOR_STOP_TIMEOUT'};$admissionAfter=Invoke-RestMethod http://127.0.0.1:9001/actuator/doengadmission;W (Join-Path $artifact 'admission-metrics-after.json') $admissionAfter;$registryAfter=Invoke-RestMethod $identityUrl;W (Join-Path $artifact 'meter-registry-after-response.json') $registryAfter;Start-Sleep -Seconds 2;$registryIdle=Invoke-RestMethod $identityUrl;W (Join-Path $artifact 'meter-registry-after-idle.json') $registryIdle;W (Join-Path $artifact 'pool-series-mapping.json') ([ordered]@{providerIdentity=$probes[0].identity.clients.TOKEN.providerIdentity;providerName=$probes[0].identity.clients.TOKEN.providerName;remoteAddresses=@($probes[0].identity.clients.Values|% baseUrl|Sort-Object -Unique);series=@($registryIdle.poolSeries);conclusion=if(@($registryIdle.poolSeries).Count -gt 0){'METER_SERIES_EXPOSED'}else{'METRICS_NOT_REGISTERED'}})
  if(Test-Path $legacy){Copy-Item -Recurse -Force (Join-Path $legacy '*') $artifact};$resolved=[ordered]@{mode=$admissionAfter.mode;enabled=$admissionAfter.admission.enabled;scope=$admissionAfter.scope;configuredLimit=$admissionAfter.admission.configuredLimit;started=$admissionAfter.admission.started;completed=$admissionAfter.admission.completed;rejected=$admissionAfter.admission.rejected;currentInUse=$admissionAfter.admission.currentInUse;released=$admissionAfter.admission.released;cancelled=$admissionAfter.admission.cancelled};W (Join-Path $artifact 'application-resolved-config.json') ([ordered]@{resolved=$resolved;admissionBefore=$admissionBefore;admissionDuring=$admissionDuring;admissionAfter=$admissionAfter;identityProbe='see pool-provider-identity.json'});W (Join-Path $artifact 'exp131-run-config.json') ([ordered]@{runId=$RunId;runDate=$RunDate;phase='completed';smokeExit=$smokeExit;admissionMode='OFF';admissionEnabled=$false;poolMode='SHARED';sharedPoolMaxConnections=$PoolMaxConnections;pendingAcquireMaxCount=800;identityProfiles=$profiles;runnerCompletedAt=[DateTimeOffset]::UtcNow.ToString('o')})
  W (Join-Path $artifact 'lifecycle-timeline.json') ([ordered]@{runId=$RunId;collectorStarted=$true;loadStarted=$true;loadStopped='see client-results.json';admissionDuringCaptured=$true;drain='see mock-drain-summary.json';finalizedAt=[DateTimeOffset]::UtcNow.ToString('o')});$verificationPath=Join-Path $artifact 'verification-summary.json';if(-not (Test-Path $verificationPath)){throw 'LIFECYCLE_VERIFICATION_MISSING'};$verification=J $verificationPath;if($verification.measurementValidity -ne 'VALID'){throw 'LIFECYCLE_SMOKE_INVALID'}
}catch{$failure=$_}finally{if($null -ne $collector -and -not $collector.HasExited){try{$collector.Kill()}catch{}};docker compose -p $project @compose down --remove-orphans|Out-Null}
if($failure){Write-Error $failure;exit 1};Write-Output "EXP131_DIAGNOSTIC_COMPLETED: $RunId"
